CREATE TABLE lehrer (
  kuerzel  TEXT PRIMARY KEY,
  vorname  TEXT NOT NULL,
  nachname TEXT NOT NULL
);

CREATE TABLE klasse (
  bez  TEXT PRIMARY KEY,
  raum TEXT,
  kv   TEXT NOT NULL UNIQUE
       REFERENCES lehrer(kuerzel)
);

CREATE TABLE schueler (
  sch_id  INTEGER PRIMARY KEY,
  vorname TEXT NOT NULL,
  strasse TEXT,
  plz     TEXT,
  ort     TEXT,
  klasse  TEXT NOT NULL
          REFERENCES klasse(bez)
);

CREATE TABLE telefon (
  sch_id INTEGER
         REFERENCES schueler(sch_id),
  nummer TEXT,
  PRIMARY KEY (sch_id, nummer)
);

CREATE TABLE buch (
  isbn  TEXT PRIMARY KEY,
  titel TEXT NOT NULL
);

CREATE TABLE exemplar (
  isbn    TEXT REFERENCES buch(isbn)
          ON DELETE CASCADE,
  nr      INTEGER,
  zustand TEXT,
  PRIMARY KEY (isbn, nr)
);

PRAGMA foreign_keys = ON;
-- HUB ist schon KV der 3AHIF:
INSERT INTO klasse
  VALUES ('3BHIF', 'E08', 'HUB');
-- UNIQUE constraint failed:
--   klasse.kv

-- Buch 978-9 gibt es nicht:
INSERT INTO exemplar
  VALUES ('978-9', 1, 'neu');
-- FOREIGN KEY constraint failed
